USE celtatravel;

UPDATE viajes SET descripcion = 'Cancún es uno de los destinos más destacados del Caribe mexicano, ideal para quienes buscan playas de arena blanca, aguas turquesas y una estancia pensada para el descanso y el disfrute. Con una zona hotelera de más de 20 kilómetros frente al mar, este destino combina la belleza natural del Caribe con una oferta de ocio, gastronomía y cultura que lo convierte en uno de los lugares más visitados del mundo. Además, su cercanía a sitios arqueológicos como Chichén Itzá, Tulum o Cobá permite combinar el relax en la playa con la exploración de la historia maya.\n\nEl viaje incluye traslados desde el aeropuerto, asistencia en destino y una amplia variedad de opciones de alojamiento para todos los gustos. Quienes buscan lujo encontrarán resorts de cinco estrellas todo incluido frente al mar con spa, piscinas infinitas y entretenimiento nocturno. Para quienes prefieren algo más íntimo, existen hoteles boutique en la zona hotelera o en el centro de la ciudad, con una atención más personalizada y precios más ajustados.' WHERE nombre = 'México - Cancún';

UPDATE viajes SET descripcion = 'Galicia es uno de los destinos más auténticos y sorprendentes de España, donde el verde intenso de sus paisajes se funde con el Atlántico en una costa de una belleza salvaje y singular. Este recorrido incluye Santiago de Compostela, con su catedral y su ambiente de peregrinos llegados de todo el mundo, las Rías Baixas con sus playas y mariscos frescos, y la Costa da Morte, uno de los tramos costeros más espectaculares de Europa. La gastronomía gallega, con el pulpo, el marisco y los vinos albariño, es por sí sola una razón de peso para visitar este rincón del noroeste español.\n\nEl viaje incluye traslados entre los distintos puntos del recorrido y asistencia durante toda la estancia. Para el alojamiento se puede elegir entre hoteles con encanto en el casco histórico de Santiago, a pocos pasos de la catedral, o pazos rurales gallegos reconvertidos en alojamientos de lujo, rodeados de naturaleza y con una cocina tradicional de primer nivel. También hay opciones más económicas en casas de turismo rural distribuidas por toda la región.' WHERE nombre = 'España - Galicia';

UPDATE viajes SET descripcion = 'Japón es uno de los destinos más fascinantes del mundo, un lugar donde la tradición milenaria y la modernidad más avanzada conviven en perfecta armonía en cada ciudad, cada templo y cada plato. Esta ruta recorre Tokio, la megalópolis más poblada del planeta, Kioto con sus templos zen y geishas, Osaka con su energía gastronómica sin igual, y Nara, donde los ciervos sagrados pasean libremente entre pagodas. La floración de los cerezos en primavera y los colores del otoño convierten este viaje en una experiencia visual que pocas veces se olvida.\n\nEl viaje incluye traslados en el mítico tren bala Shinkansen entre ciudades, guía local en español y asistencia durante toda la estancia. El alojamiento combina hoteles modernos de diseño en Tokio con ryokans tradicionales en Kioto, donde se duerme en tatami, se cena kaiseki y se disfruta de un onsen privado al amanecer. Para quienes prefieren mayor comodidad, también hay disponibles hoteles internacionales de cuatro y cinco estrellas en todas las ciudades del recorrido.' WHERE nombre = 'Japón - Tour completo';

UPDATE viajes SET descripcion = 'Granada es uno de los destinos históricos y culturales más impresionantes de España, una ciudad donde la herencia árabe, cristiana y judía se mezclan en cada calle, cada monumento y cada plato. Este viaje permite descubrir la Alhambra, declarada Patrimonio de la Humanidad y considerada una de las obras arquitectónicas más bellas del mundo, pasear por el laberíntico barrio del Albaicín con sus cármenes y miradores, y disfrutar de unas vistas únicas de Sierra Nevada al fondo. La gastronomía granadina, con sus famosas tapas gratuitas y sus restaurantes de cocina andaluza, completa una experiencia de visita difícil de superar.\n\nEl viaje incluye traslados desde el aeropuerto o la estación, entradas a los monumentos principales y asistencia durante toda la estancia. Para el alojamiento se puede elegir entre hoteles céntricos bien comunicados con todos los puntos de interés o alojamientos con encanto en el propio Albaicín, con terrazas y vistas directas a la Alhambra que hacen de cada amanecer un momento único. También hay disponibles hoteles de lujo en las afueras con spa y piscina para quienes buscan mayor descanso.' WHERE nombre = 'España - Granada';

UPDATE viajes SET descripcion = 'Fuerteventura es la isla canaria del sol y las playas infinitas, un destino que presume de más de 150 kilómetros de costa con algunas de las playas más bonitas de Europa y un clima excepcional durante los 365 días del año. Sus dunas de Corralejo, declaradas Parque Natural, sus aguas cristalinas perfectas para el windsurf y el kitesurf, y sus pueblos pesqueros como El Cotillo o Morro Jable la convierten en un destino ideal tanto para el descanso como para los amantes de los deportes acuáticos y la naturaleza.\n\nEl viaje incluye traslados desde el aeropuerto y asistencia en destino durante toda la estancia. El destino ofrece una amplia variedad de alojamientos para todos los perfiles de viajero: grandes resorts con todo incluido, spa y animación frente a las playas del sur para quienes buscan comodidad máxima, apartamentos y villas privadas con piscina para familias o grupos, y hoteles boutique más tranquilos en pueblos del norte de la isla para quienes prefieren un ambiente más auténtico y relajado.' WHERE nombre = 'España - Fuerteventura';

UPDATE viajes SET descripcion = 'Roma es la ciudad eterna, un destino que condensa más de dos mil años de historia en cada plaza, cada ruina y cada iglesia de su centro histórico, declarado Patrimonio de la Humanidad. Este viaje permite descubrir el Coliseo y el Foro Romano, visitar los Museos Vaticanos y la Capilla Sixtina, lanzar una moneda a la Fontana di Trevi y perderse por los barrios más auténticos de la capital italiana como Trastevere o Prati. La gastronomía romana, con su pasta alla carbonara, sus suppli y su gelato artesanal, añade un ingrediente más a una experiencia de visita que resulta difícil de superar.\n\nEl viaje incluye traslados desde el aeropuerto, entradas a los principales monumentos con acceso preferente y guía en español. Para el alojamiento se puede elegir entre hoteles de lujo en el centro histórico a pocos minutos a pie de los principales monumentos o pensiones familiares en barrios auténticos como Trastevere, con una atmósfera más local y precios más ajustados. También hay disponibles apartamentos turísticos para quienes prefieren mayor independencia durante su estancia en la ciudad.' WHERE nombre = 'Italia - Roma';

UPDATE viajes SET descripcion = 'Estambul es una ciudad única en el mundo, el único lugar del planeta donde dos continentes, Europa y Asia, se unen sobre el agua del Bósforo creando una mezcla irrepetible de culturas, arquitectura, gastronomía e historia. Este viaje recorre la Mezquita Azul y Santa Sofía en el corazón histórico de Sultanahmet, el laberíntico Gran Bazar con sus miles de tiendas y aromas, el opulento Palacio de Topkapi y los barrios más modernos y creativos como Beyoglu o Karakoy, donde la escena gastronómica y cultural de la ciudad late con más fuerza.\n\nEl viaje incluye traslados desde el aeropuerto, crucero por el Bósforo y asistencia en destino durante toda la estancia. El alojamiento ofrece opciones para todos los gustos: hoteles de lujo con vistas panorámicas al Bósforo y el skyline de minaretes desde sus terrazas, hoteles boutique de cuatro estrellas en el barrio histórico de Sultanahmet a pocos pasos de todos los monumentos, o establecimientos más económicos en Beyoglu, bien comunicados con el centro y rodeados de restaurantes y vida nocturna.' WHERE nombre = 'Turquía - Estambul';

UPDATE viajes SET descripcion = 'Marruecos es un destino de contrastes fascinantes donde los zocos medievales llenos de color y aroma, las montañas nevadas del Atlas y las inmensas dunas doradas del Sáhara conviven en un país de una riqueza cultural e histórica extraordinaria. Esta ruta parte de Marrakech, con su mítica plaza Djemaa el Fna y su laberíntica medina, y atraviesa el Alto Atlas y el impresionante ksar de Ait Ben Haddou, declarado Patrimonio de la Humanidad, para llegar hasta las dunas de Merzouga, donde el silencio del desierto y el cielo estrellado del Sáhara ofrecen una experiencia que pocas veces se olvida.\n\nEl viaje incluye traslados en vehículo privado por todo el recorrido, guía local en español y asistencia durante toda la estancia. Para el alojamiento se puede elegir entre riads tradicionales en la medina de Marrakech, con sus patios interiores, sus fuentes y su decoración artesanal, o campamentos de lujo en medio del desierto de Merzouga, donde se duerme en jaimas equipadas con todas las comodidades mientras se escucha el silencio absoluto del Sáhara y se disfruta de un amanecer sobre las dunas.' WHERE nombre = 'Marruecos - Ruta del desierto';

UPDATE viajes SET descripcion = 'Argentina es un país de dimensiones continentales y una diversidad de paisajes que va desde las pampas infinitas hasta los glaciares de la Patagonia, pasando por las selvas subtropicales del norte y los viñedos de Mendoza. Este viaje recorre Buenos Aires, la París de América del Sur con su arquitectura europea y su pasión por el tango, las impresionantes Cataratas de Iguazú en la frontera con Brasil, la salvaje Patagonia con sus condores y sus pumas, y el glaciar Perito Moreno, uno de los espectáculos naturales más impresionantes del planeta.\n\nEl viaje incluye vuelos internos entre los distintos destinos del recorrido, traslados y asistencia durante toda la estancia. El alojamiento combina hoteles de diseño en los barrios más elegantes de Buenos Aires como Palermo o Recoleta con lodges de naturaleza en la Patagonia, perfectamente integrados en el entorno y desde cuyas ventanas se puede contemplar el glaciar o los lagos patagónicos al despertar. También hay disponibles estancias en estancias tradicionales para quienes quieran vivir la vida gaucha de primera mano.' WHERE nombre = 'Argentina - Ruta natural';

UPDATE viajes SET descripcion = 'Perú es la cuna de la civilización inca y uno de los destinos más impresionantes y emocionantes de América del Sur, un país donde la historia milenaria, los paisajes andinos de una belleza sobrecogedora y una gastronomía reconocida como una de las mejores del mundo se combinan en una experiencia de viaje difícil de igualar. Esta ruta recorre Lima, con su vibrante escena gastronómica y su centro histórico colonial, Cusco, la antigua capital del Imperio inca rodeada de ruinas y mercados, el Valle Sagrado de los Incas y, por supuesto, la ciudadela de Machu Picchu, una de las maravillas del mundo moderno.\n\nEl viaje incluye vuelo interno a Cusco, tren panorámico al pie de Machu Picchu, entradas a todos los yacimientos y guía especializado en historia inca. Para el alojamiento se puede elegir entre hoteles boutique de lujo en el centro histórico de Cusco, instalados en antiguos palacios coloniales del siglo XVI, o el exclusivo Belmond Sanctuary Lodge junto a la puerta de Machu Picchu, el único hotel situado dentro del santuario histórico, para quienes quieran ver las ruinas al amanecer sin turistas.' WHERE nombre = 'Perú - Ruta andina';

UPDATE viajes SET descripcion = 'Kenia es el destino de safari por excelencia, el lugar donde la fauna africana se muestra en todo su esplendor en algunas de las reservas naturales más famosas y mejor conservadas del planeta. Este viaje incluye recorridos por el Masái Mara, escenario de la Gran Migración de ñus y cebras considerada el mayor espectáculo natural del mundo, el lago Nakuru con sus flamencos rosados, y el Parque Nacional de Amboseli con el imponente Kilimanjaro como telón de fondo. La posibilidad de avistar a los cinco grandes, el elefante, el león, el leopardo, el búfalo y el rinoceronte, convierte cada salida en una experiencia única e irrepetible.\n\nEl viaje incluye todos los traslados en vehículo 4x4 con techo abatible para los safaris, guía naturalista en español y pensión completa durante las estancias en las reservas. El alojamiento va desde lodges de lujo perfectamente integrados en la sabana, con terrazas desde las que se pueden ver los animales pasar al amanecer, hasta campamentos más básicos pero auténticos para quienes buscan una experiencia más cercana a la naturaleza y a la cultura masái.' WHERE nombre = 'Kenia - Safari';

UPDATE viajes SET descripcion = 'China es un país de historia milenaria, contrastes fascinantes y una escala que lo convierte en un destino único en el mundo, donde conviven la Gran Muralla y los rascacielos de cristal, los mercados tradicionales y los centros comerciales más modernos del planeta. Este tour imperial recorre Pekín con la Ciudad Prohibida y el Templo del Cielo, Xi\'an con los famosos guerreros de terracota del ejército del primer emperador, y Shanghái, la ciudad más cosmopolita y dinámica del país, con su skyline futurista y su antiguo barrio histórico del Bund frente al río Huangpu.\n\nEl viaje incluye traslados en tren de alta velocidad entre ciudades, guía local en español y asistencia durante toda la estancia. El alojamiento combina hoteles internacionales de cinco estrellas en el centro de las grandes ciudades con casas de huéspedes tradicionales en los hutongs históricos de Pekín, los estrechos callejones del barrio antiguo que dan una visión completamente diferente y más auténtica de la vida cotidiana china.' WHERE nombre = 'China - Tour imperial';

UPDATE viajes SET descripcion = 'Egipto es uno de los destinos históricos más impresionantes y emocionantes del planeta, un país donde la civilización más antigua del mundo dejó monumentos de una escala y una belleza que siguen asombrando a los viajeros después de más de cuatro mil años. Esta ruta faraónica recorre El Cairo con el Museo Egipcio y las pirámides de Giza y la Gran Esfinge, sube por el Nilo hasta Luxor con el Valle de los Reyes y el Templo de Karnak, y llega hasta Asuán y los templos de Abu Simbel, salvados de las aguas en una de las mayores operaciones de rescate arqueológico de la historia.\n\nEl viaje incluye crucero de cuatro noches por el Nilo entre Luxor y Asuán, traslados en vehículo privado, entradas a todos los monumentos y guía especializado en egiptología. El alojamiento combina hoteles históricos de gran tradición viajera en El Cairo, algunos con vistas directas a las pirámides desde sus terrazas, con los camarotes del crucero por el Nilo, una experiencia única que permite despertar cada mañana frente a un templo diferente en la orilla del río.' WHERE nombre = 'Egipto - Ruta faraónica';

UPDATE viajes SET descripcion = 'Jordania es un destino de historia extraordinaria y paisajes únicos en Oriente Medio, un país pequeño pero de una riqueza arqueológica y natural que sorprende a todos los viajeros que lo visitan. Este viaje recorre Amán, la capital con su ciudadela romana y su vibrante vida urbana, la ciudad rosa de Petra, tallada en la roca por los nabateos hace más de dos mil años y considerada una de las maravillas del mundo moderno, el desierto de Wadi Rum con sus formaciones rocosas de colores imposibles y el Mar Muerto, donde flotar sin esfuerzo a menos 430 metros bajo el nivel del mar es una experiencia obligatoria.\n\nEl viaje incluye traslados en vehículo privado por todo el recorrido, entradas a Petra y demás yacimientos y asistencia durante toda la estancia. Se puede dormir en hoteles modernos de cuatro estrellas en el centro de Amán, campamentos beduinos de lujo en Wadi Rum con jaimas totalmente equipadas y terrazas para contemplar las estrellas del desierto, o en las míticas cuevas de Petra habilitadas como alojamiento, una experiencia completamente única que pocas veces se encuentra en cualquier otro destino del mundo.' WHERE nombre = 'Jordania - Ruta del desierto';

UPDATE viajes SET descripcion = 'Grecia es la cuna de la civilización occidental, un país donde cada piedra cuenta una historia de más de tres mil años de filosofía, arte, democracia y mitología que sigue siendo la base de nuestra cultura. Esta ruta clásica recorre Atenas con la Acrópolis y el Partenón, el santuario de Delfos en las laderas del Parnaso, los monasterios de Meteora suspendidos sobre rocas gigantescas, y algunas de las islas más emblemáticas del archipiélago griego, con sus casas encaladas, sus iglesias de cúpula azul y sus atardeceres sobre el mar Egeo.\n\nEl viaje incluye traslados en ferry entre las islas, entradas a los principales yacimientos arqueológicos y asistencia durante toda la estancia. El alojamiento combina hoteles céntricos en Atenas bien situados para visitar la Acrópolis con las características casas encaladas reconvertidas en hoteles boutique en las islas, algunas con piscina privada tallada en la roca con vistas panorámicas al mar Egeo que se han convertido en uno de los iconos fotográficos más reconocibles del mundo.' WHERE nombre = 'Grecia - Ruta clásica e islas';

UPDATE viajes SET descripcion = 'Australia es el continente más salvaje, diverso y sorprendente del planeta, un país donde la Gran Barrera de Coral, el mayor sistema de arrecifes del mundo, convive con el desierto rojo del Outback, las playas urbanas de Sídney y los bosques de eucaliptos habitados por canguros y koalas. Este viaje recorre Sídney, con su icónica Ópera y su puente sobre el puerto, Cairns como puerta de entrada a la Gran Barrera de Coral, y el corazón del país con el imponente Uluru, la roca sagrada de los aborígenes que cambia de color con la luz del atardecer.\n\nEl viaje incluye vuelos internos entre los distintos destinos, excursión en barco con snorkel en la Gran Barrera de Coral y asistencia durante toda la estancia. El alojamiento combina hoteles de diseño con vistas al puerto de Sídney o a la Opera House, eco-lodges junto a la Gran Barrera de Coral comprometidos con la conservación del arrecife, y estaciones ganaderas históricas del Outback reconvertidas en alojamientos rurales únicos donde se puede vivir la experiencia de la vida en el interior australiano.' WHERE nombre = 'Australia - Ruta oceánica';

UPDATE viajes SET descripcion = 'Nueva Zelanda es uno de los países más hermosos y espectaculares del mundo, un archipiélago en el fin del mundo donde los paisajes cambian radicalmente cada pocos kilómetros, desde volcanes activos y géiseres hasta fiordos de aguas negras, playas de arena dorada, glaciares que llegan hasta el mar y praderas verdes de una intensidad que parece irreal. Esta ruta natural recorre la Isla Norte con Rotorua y su actividad geotérmica y la vibrante Auckland, y la Isla Sur con el fiordo de Milford Sound, los Alpes del Sur y la aventurera Queenstown, capital mundial del turismo de aventura.\n\nEl viaje incluye alquiler de vehículo para mayor libertad de movimiento, travesía en ferry entre las dos islas y asistencia durante toda la estancia. El alojamiento combina hoteles boutique con carácter en ciudades como Auckland o Queenstown con lodges de naturaleza en zonas remotas de la Isla Sur, rodeados de una naturaleza prácticamente virgen y desde cuyas ventanas se pueden contemplar los Alpes del Sur, los fiordos o los glaciares en un silencio y una paz difíciles de encontrar en cualquier otro destino del mundo.' WHERE nombre = 'Nueva Zelanda - Ruta natural';

UPDATE viajes SET descripcion = 'Escocia es un destino de historia milenaria, misterio y paisajes verdes e infinitos que ha conquistado la imaginación de viajeros de todo el mundo con sus castillos en ruinas, sus highlands salvajes, sus lochs de aguas oscuras y su cultura celta de una riqueza y una autenticidad extraordinarias. Esta ruta de castillos recorre Edimburgo, una de las ciudades más bonitas de Europa con su castillo sobre la roca volcánica y su casco histórico medieval, las Highlands con sus valles glaciares y sus pueblos de piedra, y el famoso Lago Ness, cuyas aguas guardan uno de los misterios más populares del mundo.\n\nEl viaje incluye traslados en vehículo privado por las Highlands, visitas guiadas a los principales castillos y asistencia durante toda la estancia. El alojamiento combina hoteles históricos en el casco antiguo de Edimburgo, algunos instalados en edificios del siglo XVIII con vistas al castillo, con castillos reconvertidos en hoteles de lujo en las Highlands donde se puede cenar en un comedor con chimenea y armaduras en las paredes, y acogedoras posadas rurales llamadas country houses perfectas para descansar en plena naturaleza escocesa.' WHERE nombre = 'Escocia - Ruta de castillos';

UPDATE viajes SET descripcion = 'París es la ciudad del amor, la cultura y la gastronomía por excelencia, una capital que lleva siglos siendo el centro del mundo en moda, arte, literatura y pensamiento, y que sigue siendo capaz de sorprender y enamorar a cualquier viajero que la visita por primera o por décima vez. Esta escapada recorre los grandes iconos de la ciudad, la Torre Eiffel, el Museo del Louvre con la Mona Lisa, la Catedral de Notre Dame en plena reconstrucción, el barrio de Montmartre con su Sacré-Coeur y sus artistas, y los elegantes bulevares diseñados por Haussmann en el siglo XIX que le dieron a París su imagen actual.\n\nEl viaje incluye traslados desde el aeropuerto, entradas a los principales museos con acceso preferente sin colas y asistencia durante toda la estancia. El alojamiento va desde hoteles de gran lujo en los Campos Elíseos o cerca de la Torre Eiffel para quienes quieren vivir París en su versión más glamurosa, hasta encantadores hoteles boutique en el Barrio Latino o en Le Marais, el barrio más moderno y creativo de la ciudad, perfectos para quienes prefieren descubrir la ciudad como un parisino más.' WHERE nombre = 'Francia - París';

UPDATE viajes SET descripcion = 'México tiene una riqueza cultural, histórica y gastronómica extraordinaria que lo convierte en uno de los destinos más fascinantes y completos del continente americano, un país donde las pirámides precolombinas, la arquitectura colonial española, los mercados indígenas y la cocina reconocida por la UNESCO como Patrimonio Inmaterial de la Humanidad crean una experiencia de viaje de una intensidad difícil de igualar. Esta ruta colonial recorre Ciudad de México con el Zócalo y el Museo Nacional de Antropología, la barroca Puebla de los Ángeles y la mágica Oaxaca, capital del mezcal y del mole negro.\n\nEl viaje incluye traslados entre ciudades, entradas a los principales sitios arqueológicos y museos y asistencia durante toda la estancia. El alojamiento combina hoteles de diseño en el centro histórico de Ciudad de México, algunos instalados en palacios coloniales con patios interiores de azulejos, con casas coloniales reconvertidas en hoteles boutique de gran encanto en Oaxaca, rodeadas de mercados de artesanía, mezcalerías y restaurantes de cocina tradicional oaxaqueña considerada una de las más complejas y ricas de todo México.' WHERE nombre = 'México - Ruta colonial';

UPDATE viajes SET descripcion = 'Brasil es un país de energía desbordante, naturaleza exuberante y una cultura de una alegría y una vitalidad que se contagia desde el primer momento, un destino donde el carnaval, el fútbol, la samba y las playas más famosas del mundo conviven con una biodiversidad única en el planeta y una gastronomía mestiza de raíces indígenas, africanas y europeas. Este viaje se centra en Río de Janeiro, la ciudad maravillosa, con sus playas de Copacabana e Ipanema, el Cristo Redentor sobre el Corcovado, el Pan de Azúcar y los barrios históricos de Santa Teresa y Lapa.\n\nEl viaje incluye traslados desde el aeropuerto, subida en teleférico al Pan de Azúcar y al Corcovado y asistencia durante toda la estancia. El alojamiento combina hoteles frente a las playas de Copacabana o Ipanema para quienes quieren despertar con el sonido del Atlántico cada mañana, con pousadas más íntimas y con carácter en los barrios históricos de Santa Teresa o Lapa, donde la escena cultural y nocturna de Río late con más fuerza y autenticidad.' WHERE nombre = 'Brasil - Río y naturaleza';

UPDATE viajes SET descripcion = 'Sudáfrica es un destino único en el mundo que combina paisajes africanos de una belleza y una diversidad extraordinarias con ciudades cosmopolitas y modernas, una historia reciente de una profundidad y una complejidad únicas y una fauna salvaje de una riqueza que pocos países del mundo pueden igualar. Esta ruta recorre Ciudad del Cabo, una de las ciudades más bellas del planeta con la Montaña de la Mesa como telón de fondo, la Ruta Jardín a lo largo de la costa, y varias reservas naturales para disfrutar de safaris en busca de los cinco grandes en su hábitat natural.\n\nEl viaje incluye traslados en vehículo privado por todo el recorrido, safaris guiados en las reservas y asistencia durante toda la estancia. El alojamiento combina hoteles de diseño en Ciudad del Cabo con vistas a la Montaña de la Mesa o a la bahía, con lodges privados en plena reserva natural donde la única separación entre los huéspedes y la sabana africana es una valla electrificada, y desde cuyas terrazas se pueden ver elefantes, jirafas o leones pasar al amanecer.' WHERE nombre = 'Sudáfrica - Safari y Ciudad del Cabo';

UPDATE viajes SET descripcion = 'Tailandia es el destino asiático por excelencia, un país que ha conquistado a millones de viajeros de todo el mundo con su combinación irresistible de templos budistas de una belleza deslumbrante, playas tropicales de arena blanca y aguas cristalinas, mercados flotantes llenos de color y aroma, y una gastronomía exótica y picante que se ha convertido en una de las más populares del mundo. Este tour recorre Bangkok, la caótica y fascinante capital con sus templos dorados y sus mercados nocturnos, y las playas del sur en Koh Samui o Krabi, con sus acantilados de piedra caliza cayendo al mar turquesa.\n\nEl viaje incluye vuelo interno a las islas del sur, traslados en barco entre las diferentes playas y asistencia durante toda la estancia. El alojamiento combina hoteles modernos de diseño en el centro de Bangkok bien situados para explorar la ciudad, resorts de lujo frente al mar en Koh Samui con piscina privada y vistas al Golfo de Tailandia, y bungalows más económicos pero igualmente encantadores en playas menos masificadas para quienes prefieren un ambiente más tranquilo y auténtico.' WHERE nombre = 'Tailandia - Bangkok y playas';

UPDATE viajes SET descripcion = 'Italia enamora en cada paso con su arte inagotable, su historia de más de dos mil años presente en cada piedra de sus ciudades, su gastronomía de una variedad y una calidad incomparables y su forma de vivir, la dolce vita, que se convierte en el modelo de vida soñado de millones de personas en todo el mundo. Esta ruta clásica del norte recorre Milán, capital de la moda y el diseño con el Duomo y La Última Cena de Leonardo da Vinci, la universitaria y gastronómica Bolonia, Florencia con los Uffizi y el David de Miguel Ángel, y Venecia, la ciudad más romántica y singular del mundo construida sobre el agua.\n\nEl viaje incluye traslados en tren de alta velocidad entre ciudades, entradas con acceso preferente a los principales museos y asistencia durante toda la estancia. El alojamiento combina hoteles de diseño en los barrios más elegantes de Milán con pensiones familiares de gran encanto en Florencia y los característicos hoteles sobre el Gran Canal de Venecia, donde el sonido del agua y el paso de las góndolas bajo la ventana crean una atmósfera completamente única que convierte cada noche en Venecia en una experiencia memorable.' WHERE nombre = 'Italia - Ruta clásica';

UPDATE viajes SET descripcion = 'Canadá es un país de dimensiones continentales y una naturaleza de una escala y una espectacularidad que pocas veces se encuentran en otro lugar del mundo, un destino donde las ciudades más cosmopolitas y multiculturales de Norteamérica conviven con bosques infinitos, lagos de color turquesa, osos pardos pescando salmones y las Cataratas del Niágara, uno de los espectáculos naturales más impresionantes del planeta. Este recorrido visita Toronto, la ciudad más grande y diversa de Canadá con su icónica CN Tower, la francófona y elegante Montreal con su casco histórico europeo, y las propias Cataratas del Niágara.\n\nEl viaje incluye traslados entre ciudades, crucero al pie de las Cataratas del Niágara y asistencia durante toda la estancia. El alojamiento combina hoteles urbanos de lujo en el centro de Toronto o Montreal, perfectamente situados para explorar las ciudades a pie, con lodges de naturaleza junto a las Cataratas del Niágara con vistas directas al agua desde las habitaciones, donde el rugido constante de los miles de metros cúbicos de agua cayendo cada segundo se convierte en la banda sonora de una estancia verdaderamente inolvidable.' WHERE nombre = 'Canadá - Naturaleza y ciudades';


